interface.definition:
#"SYSTEM_SYSRULES_formLayout_v1"(
  label: "Cancel Rotational Ask: " &
    concat(
      "Rotational " & ri!rotationalaskview.askName & " : " & ri!rotationalaskview.askId & " - V" & ri!rotationalaskview.version
    )
   & " - " & ri!rotationalaskview.askId,
  contents: {
    #"SYSTEM_SYSRULES_boxLayout"(
      label: "Rotational Details",
      contents: {
        #"SYSTEM_SYSRULES_columnsLayout"(
          spacing: "DENSE",
          columns: {
            #"SYSTEM_SYSRULES_columnLayout"(
              width: "NARROW",
              contents: {
                #"SYSTEM_SYSRULES_textField"(
                  label: "Name of the ASK",
                  value: #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3412447"(value: ri!rotationalaskview.askName),
                  readOnly: true
                ),

              }
            ),
            /*a!columnLayout(*/
            /*contents: {*/
            /*a!textField(*/
            /*label: "DPP Group",*/
            /*value: rule!CAW_displayReadOnlyField(value: ri!coreAsksView.dppGroup),*/
            /*readOnly: true*/
            /*)*/
            /*                */
            /*}*/
            /*),*/
            #"SYSTEM_SYSRULES_columnLayout"(
              contents: {
                #"SYSTEM_SYSRULES_textField"(
                  label: "Fiscal Year",
                  value: #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3412447"(value: ri!rotationalaskview.fYear),
                  readOnly: true
                )
              }
            ),
            #"SYSTEM_SYSRULES_columnLayout"(
              contents: {
                #"SYSTEM_SYSRULES_textField"(
                  label: "Version",
                  value: #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3412447"(value: ri!rotationalaskview.version),
                  readOnly: true
                )
              }
            ),
            #"SYSTEM_SYSRULES_columnLayout"(
              contents: {
                #"SYSTEM_SYSRULES_textField"(
                  label: "Request #",
                  value: #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3412447"(value: ri!rotationalaskview.askId),
                  readOnly: true
                )
              }
            )
          },

        )
      },
      style: "ACCENT",
      marginBelow: "STANDARD"
    ),
    #"SYSTEM_SYSRULES_boxLayout"(
      label: "Cancellation Comment",
      contents: {
        #"SYSTEM_SYSRULES_paragraphField"(
          label: "",
          labelPosition: "COLLAPSED",
          value: index(ri!comment, "comment", {}),
          saveInto: ri!comment.comment,
          characterLimit: #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3238137",
          required: true,
          requiredMessage: "A comment is required to cancel this nomination"
        )
      },
      isCollapsible: false,
      marginBelow: "STANDARD",
      style: "ACCENT"
    )
  },
  buttons: #"SYSTEM_SYSRULES_ButtonLayout"(
    primaryButtons: {
      #"SYSTEM_SYSRULES_ButtonWidget"(
        label: #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3155707",
        value: #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3155707",
        submit: true,
        style: "PRIMARY",
        validate: true,
        confirmMessage: "Are you sure you want to cancel this nomination. This action cannot be undone.",
        loadingIndicator: true,
        saveInto: {
          ri!buttonClicked,
          a!save(
            ri!ask.statusId,
            #"_a-0000e6d2-8270-8000-9c03-011c48011c48_3891969"
          ),
          /*COMMENT LOGIC*/
          a!save(
            ri!comment,
            'type!{urn:com:appian:types:CAW}CAW_Comment'(
              commentId: null,
              requestId: index(ri!rotationalaskview, "askId", null),
              moduleTypeId: #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3164387",
              comment: property(ri!comment, "comment", null),
              isDraft: false,
              isActive: true,
              version: 1,
              createdBy: loggedInUser(),
              createdOn: now(),
              modifiedBy: loggedInUser(),
              modifiedOn: now()
            )
          ),
          /*AUDIT*/
          a!save(
            ri!auditHistory,
            'type!{urn:com:appian:types:CAW}CAW_Audit'(
              auditId: null,
              taskId: null,
              requestId: ri!rotationalaskview.askId,
              moduleTypeId: #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3164387",
              statusId: #"_a-0000ef82-c68c-8000-9c6c-011c48011c48_14274552",
              version: 1,
              action: "Rotational Ask Cancelled",
              description: index(ri!comment, "comment", {}),
              createdBy: loggedInUser(),
              createdOn: now()
            )
          ),
          /*a!save(ri!coreAsksView.askID, null),*/
          a!save(
            ri!ask.modifiedBy,
            #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3052910"(loggedInUser())
          ),
          a!save(ri!ask.modifiedOn, now())
        }
      )
    },
    secondaryButtons: {
      #"SYSTEM_SYSRULES_ButtonWidget"(
        label: #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3155700",
        value: #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3155700",
        saveInto: { ri!buttonClicked },
        submit: true,
        style: "NORMAL",
        validate: false
      )
    }
  )
)
